mapper.select:
select ps.`applicant_id` as `userId`,
sum(timestampdiff(MINUTE ,ps.`start_time`,ps.`end_time`)) as `leavePostDuration`
from `leave_post_situation` ps
where ps.`deleted` = 0

    and ps.`applicant_id` = #{param.userId}


    and ps.`applicant_id` in

        #{id}



    and ps.`start_time` >= #{param.period.begin}


    and ps.`start_time` < #{param.period.end}

group by ps.`applicant_id`

select ps.`applicant_id` as `staff_Id`,
sum(timestampdiff(MINUTE ,ps.`start_time`,ps.`end_time`)) as `leave_Post_Duration`
from `leave_post_situation` ps
where ps.`deleted` = 0

    and ps.`applicant_id` = #{param.userId}


    and ps.`applicant_id` in

        #{id}



    and ps.`start_time` >= #{param.period.begin}


    and ps.`start_time` < #{param.period.end}

group by ps.`applicant_id`
